def build(lang, col):
    html = SRC.read_text(encoding="utf-8")
    errors = []
    for row in STRINGS:
        es, new, expected = row[0], row[col], (row[3] if len(row) > 3 else 1)
        found = html.count(es)
        if found != expected:
            errors.append(f"  esperado {expected}×, encontrado {found}×: {es[:90]!r}")
            continue
        html = html.replace(es, new)
    if errors:
        sys.exit(f"[{lang}] index.html ha cambiado; actualiza estas filas de STRINGS:\n" + "\n".join(errors))
    out = ROOT / lang / "index.html"
    out.parent.mkdir(exist_ok=True)
    out.write_text(html, encoding="utf-8")
    print(f"OK  {out.relative_to(ROOT)}")


if __name__ == "__main__":
    build("ca", 1)
    build("en", 2)
